using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"Sample serialize: {JsonSerializer.Serialize(new Person("Alice", 30), personInfo)}");
Console.WriteLine();

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about Person, so Widget will fail the probe.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Artificially reject anything that isn't Person
            if (ti.Type != typeof(Person))
                ti.Kind = JsonTypeInfoKind.None; // marks it unsupported
        })
};

bool hasPerson = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pInfo);
bool hasWidget = limited.TryGetTypeInfo(typeof(Widget), out JsonTypeInfo? wInfo);

Console.WriteLine($"Has metadata for Person? {hasPerson} (info null? {pInfo is null})");
Console.WriteLine($"Has metadata for Widget? {hasWidget} (info null? {wInfo is null})");

// Records used in the demo
public record Person(string Name, int Age);
public record Widget(string Id, decimal Price);

